def __getattr__(name):
    """
    Lazily create the ``RotatedSun<Frame>`` class requested by name.

    The rotated-Sun frame classes are generated on demand for each base frame.
    Astropy's table serialization reconstructs mixin columns by importing the
    fully-qualified class name stored in the serialized metadata, so these
    generated classes must be importable even in a fresh process that has not
    yet created that particular class.  This module-level ``__getattr__``
    allows such lookups to create and return the requested class.
    """
    prefix = "RotatedSun"
    if name.startswith(prefix) and name != RotatedSunFrame.__name__:
        base_name = name[len(prefix):]
        for cls in frame_transform_graph.frame_set:
            if cls.__name__ == base_name:
                return _make_rotatedsun_cls(cls)

    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

